// Check 09 (#995 gap 3, G16-adapter-mounts call 4): a journey sends to a mount's stand-in, and reads what it answers.
//
// Three adapters are generated by the real command (`ortho new adapter <name> --from-openapi`) into a copy of acme and mounted:
// `rates` as `pricing` and `fx-rates` as `fx-backup`, each `Stand.process(...)` with a stand-in this check writes (`stand.mjs`),
// and `open`, `Stand.none`. prove starts the two stand-ins (call 3, gap 2's checks, `08-prove-stand-ins.test.ts`). The stand-in
// logs every request it takes to a file this check reads, and answers its own control routes:
//   POST /_stand/seed   → 200 { token: "<plugin>-seed", plugin }
//   POST /_stand/echo   → 200 { echoed: <the body as sent>, plugin }
//   POST /_stand/refuse → 409 { error: "held" }
//
// The contract judged (G16-adapter-mounts call 4, GOAL17-check-harness call 0's `Stand.command`):
//  - `Stand.command<Args, Answer>(mount, name)(args)` is a step's call; prove POSTs `args` as JSON to
//    `<ORTHO_STAND_<MOUNT>>/_stand/<name>`, the mount's own stand-in, once;
//  - a 2xx JSON answer is the step's answer: the step's checks judge it, and it is `s.last`, so a later step's args can name it;
//  - a non-2xx fails the step, naming the mount, the command and the status; so does a mount with no stand-in running, and then
//    nothing is sent anywhere.
//
// Real workerd, a port from the OS. Written by the checks author; a builder never edits this file.
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { acme, cli, copyOf, nothingRunning } from "../layer1/support.ts";

const spec = (title: string) => ({
  openapi: "3.0.3",
  info: { title, version: "1.0.0" },
  servers: [{ url: `https://${title.toLowerCase()}.example.invalid/v1` }],
  paths: {
    "/quotes/{pair}": {
      get: {
        operationId: "quotes/get",
        parameters: [{ name: "pair", in: "path", required: true, schema: { type: "string" } }],
        responses: { "200": { description: "A quote", content: { "application/json": { schema: {
          type: "object", required: ["pair", "rate"], properties: { pair: { type: "string" }, rate: { type: "string" } } } } } } },
      },
    },
  },
});

/** The stand-in for `plugin`, logging every request to `log` (its path is baked in: it needs nothing from prove's environment). */
const standInOf = (plugin: string, log: string) => `// A stand-in written by check 09.
import { appendFileSync } from "node:fs";
import { createServer } from "node:http";

const write = (entry) => appendFileSync(${JSON.stringify(log)}, JSON.stringify({ plugin: ${JSON.stringify(plugin)}, ...entry }) + "\\n");
const server = createServer((request, response) => {
  let raw = "";
  request.on("data", (c) => { raw += c; });
  request.on("end", () => {
    write({ method: request.method, url: request.url, type: request.headers["content-type"] ?? null, raw });
    let body = null;
    try { body = JSON.parse(raw); } catch {}
    const send = (status, answer) => { response.writeHead(status, { "content-type": "application/json" }); response.end(JSON.stringify(answer)); };
    if (request.method === "POST" && request.url === "/_stand/seed") return send(200, { token: ${JSON.stringify(`${plugin}-seed`)}, plugin: ${JSON.stringify(plugin)} });
    if (request.method === "POST" && request.url === "/_stand/echo") return send(200, { echoed: body, plugin: ${JSON.stringify(plugin)} });
    if (request.method === "POST" && request.url === "/_stand/refuse") return send(409, { error: "held" });
    return send(404, { error: "no such route" });
  });
});
const args = process.argv.slice(2);
const port = args.includes("--port") ? Number(args[args.indexOf("--port") + 1]) : 0;
server.listen(port, "127.0.0.1", () => console.log("stand-in listening on http://127.0.0.1:" + server.address().port));
`;

const mountOf = (name: string) => `import { Blueprint } from "orthograph";
import adapter from "@orthograph/${name}";

export default Blueprint.use(adapter, (a) => [a.include(a.calls.quotes.get)]);
`;

// The journeys, each run alone with `ortho prove --only`. Each is red until a stand-call step exists (on main, `Stand.command` is
// not a function, so the journey file does not load).
const JOURNEYS: Readonly<Record<string, string>> = {
  "the-stand-ins-answer": `import { Blueprint, Stand, expect } from "orthograph";

const seed = Stand.command<{ pair: string }, { token: string; plugin: string }>("pricing", "seed");
const echo = Stand.command<{ from: string; n: number }, { echoed: { from: string; n: number }; plugin: string }>("fx-backup", "echo");

export default Blueprint.journey("the stand-ins answer", {
  cast: { visitor: Blueprint.anyone },
  steps: (s) => [
    s.step("pricing's stand-in seeds", seed({ pair: "EURUSD" }), expect((a) => a.token).toBe("rates-seed"), expect((a) => a.plugin).toBe("rates")),
    s.step("fx-backup's stand-in is sent what pricing's answered", echo({ from: s.last.token, n: 2 }),
      expect((a) => a.echoed.from).toBe("rates-seed"), expect((a) => a.plugin).toBe("fx-rates")),
  ],
});
`,
  "a-check-on-a-stand-in-is-judged": `import { Blueprint, Stand, expect } from "orthograph";

const seed = Stand.command<{ pair: string }, { token: string }>("pricing", "seed");

export default Blueprint.journey("a check on a stand-in is judged", {
  cast: { visitor: Blueprint.anyone },
  steps: (s) => [
    s.step("a check the answer does not meet", seed({ pair: "GBPUSD" }), expect((a) => a.token).toBe("not-the-token")),
  ],
});
`,
  "a-stand-in-refuses": `import { Blueprint, Stand } from "orthograph";

const refuse = Stand.command<{ why: string }, unknown>("pricing", "refuse");

export default Blueprint.journey("a stand-in refuses", {
  cast: { visitor: Blueprint.anyone },
  steps: (s) => [
    s.step("a command the stand-in holds", refuse({ why: "held" })),
  ],
});
`,
  "a-mount-with-no-stand-in": `import { Blueprint, Stand } from "orthograph";

const seed = Stand.command<{ pair: string }, unknown>("open", "seed");

export default Blueprint.journey("a mount with no stand-in", {
  cast: { visitor: Blueprint.anyone },
  steps: (s) => [
    s.step("a command with nothing to answer it", seed({ pair: "EURUSD" })),
  ],
});
`,
};

const ADAPTERS = {
  rates: { mount: "pricing", stand: 'Stand.process("check 09\'s stand-in for rates")' },
  "fx-rates": { mount: "fx-backup", stand: 'Stand.process("check 09\'s stand-in for fx-rates")' },
  open: { mount: "open", stand: "Stand.none" },
} as const;

interface Entry { readonly plugin: string; readonly method: string; readonly url: string; readonly type: string | null; readonly raw: string }
const entriesOf = (log: string): ReadonlyArray<Entry> =>
  existsSync(log) ? readFileSync(log, "utf8").split("\n").filter((l) => l !== "").map((l) => JSON.parse(l) as Entry) : [];

interface App { readonly root: string; readonly log: string; readonly remove: () => void }
const apps: Array<App> = [];
afterEach(() => { for (const app of apps.splice(0)) app.remove(); });

const ortho = (root: string, ...args: ReadonlyArray<string>) => {
  const said = spawnSync(process.execPath, [cli, ...args, "--root", root], { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024, timeout: 240_000 });
  return { status: said.status, out: `${said.stdout}${said.stderr}` };
};
const succeeds = (root: string, ...args: ReadonlyArray<string>) => {
  const said = ortho(root, ...args);
  expect(said.status, `ortho ${args.join(" ")}:\n${said.out}`).toBe(0);
  return said;
};

/** A copy of acme with the three adapters generated, installed and mounted, and the four journeys. */
const app = (): App => {
  const copy = copyOf(acme);
  const log = join(copy.root, "..", "stands.log");
  const made = { ...copy, log };
  apps.push(made);
  const { root } = copy;
  const scope = join(root, "node_modules/@orthograph");
  rmSync(scope);
  mkdirSync(scope);
  for (const entry of readdirSync(join(acme, "node_modules/@orthograph"))) symlinkSync(join(acme, "node_modules/@orthograph", entry), join(scope, entry));
  const specs = join(root, ".specs");
  mkdirSync(specs);
  const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as { dependencies: Record<string, string> };
  mkdirSync(join(root, "blueprint/adapters"), { recursive: true });
  for (const [name, { mount, stand }] of Object.entries(ADAPTERS)) {
    writeFileSync(join(specs, `${name}.json`), JSON.stringify(spec(name[0]!.toUpperCase() + name.slice(1))));
    succeeds(root, "new", "adapter", name, "--from-openapi", join(specs, `${name}.json`));
    const plugin = join(root, "plugins", name);
    writeFileSync(join(plugin, "stand.mjs"), standInOf(name, log));
    const manifest = JSON.parse(readFileSync(join(plugin, "package.json"), "utf8")) as { orthograph: Record<string, unknown> };
    manifest.orthograph["standIn"] = "stand.mjs";
    writeFileSync(join(plugin, "package.json"), JSON.stringify(manifest, null, 2));
    if (stand !== "Stand.none") {
      const written = join(plugin, "src/written.ts");
      const before = readFileSync(written, "utf8");
      const after = before.replace("export const standIn = Stand.none;", `export const standIn = ${stand};`);
      expect(after, `${written} scaffolds \`export const standIn = Stand.none;\``).not.toBe(before);
      writeFileSync(written, after);
    }
    symlinkSync(plugin, join(scope, name));
    pkg.dependencies[`@orthograph/${name}`] = "0.0.0";
    writeFileSync(join(root, `blueprint/adapters/${mount}.ts`), mountOf(name));
  }
  writeFileSync(join(root, "package.json"), JSON.stringify(pkg, null, 2));
  for (const [file, text] of Object.entries(JOURNEYS)) writeFileSync(join(root, `journeys/${file}.ts`), text);
  succeeds(root, "generate");
  return made;
};

/** `ortho prove` of one journey. Its exit is acme's whole verdict (`--only` still judges every operation's evals), so a test reads the journey's own lines. */
const prove = (root: string, journey: string) => ortho(root, "prove", "--env", "local", "--only", journey);
/** The journey's verdict line and what its step lines say (`  ✘ "<step>": <what>`, the title cut off, so a word in a title never counts). */
const linesOf = (out: string, journey: string) => {
  const lines = out.split("\n");
  const at = lines.findIndex((l) => l.startsWith(`journey ${journey} `));
  if (at < 0) return { verdict: undefined, steps: [] as ReadonlyArray<string> };
  const steps: Array<string> = [];
  for (const l of lines.slice(at + 1)) { if (!l.startsWith("  ")) break; steps.push(l.replace(/^\s+\S+ "[^"]*": /, "")); }
  return { verdict: lines[at], steps };
};

describe("09 a journey reaches a mount's stand-in", () => {
  it("a stand-call POSTs its args as JSON to the mount's own stand-in at /_stand/<name>; the answer is judged and is s.last for the next step", () => {
    const { root, log } = app();
    const proved = prove(root, "the stand-ins answer");
    const asked = entriesOf(log).filter((e) => e.url.startsWith("/_stand/"));
    expect(asked.map((e) => ({ plugin: e.plugin, method: e.method, url: e.url, json: (e.type ?? "").startsWith("application/json"), body: JSON.parse(e.raw || "null") as unknown })), proved.out).toEqual([
      { plugin: "rates", method: "POST", url: "/_stand/seed", json: true, body: { pair: "EURUSD" } },
      { plugin: "fx-rates", method: "POST", url: "/_stand/echo", json: true, body: { from: "rates-seed", n: 2 } },
    ]);
    expect(linesOf(proved.out, "the stand-ins answer").verdict, proved.out).toBe("journey the stand-ins answer ✔ 2/2 steps");
    nothingRunning(root);
  });

  it("a stand-call's checks judge its answer: one the answer does not meet fails the step", () => {
    const { root, log } = app();
    const proved = prove(root, "a check on a stand-in is judged");
    // The call was made, so the failure is the check's, not a call that never went.
    expect(entriesOf(log).filter((e) => e.url === "/_stand/seed").map((e) => e.plugin), proved.out).toEqual(["rates"]);
    const { verdict, steps } = linesOf(proved.out, "a check on a stand-in is judged");
    expect(verdict, proved.out).toBe("journey a check on a stand-in is judged ✘ 0/1 steps");
    expect(steps.join("\n"), proved.out).toMatch(/not-the-token/);
    nothingRunning(root);
  });

  it("a non-2xx answer fails the step, naming the mount, the command and the status", () => {
    const { root, log } = app();
    const proved = prove(root, "a stand-in refuses");
    expect(entriesOf(log).filter((e) => e.url === "/_stand/refuse").map((e) => e.plugin), proved.out).toEqual(["rates"]);
    const { verdict, steps } = linesOf(proved.out, "a stand-in refuses");
    expect(verdict, proved.out).toBe("journey a stand-in refuses ✘ 0/1 steps");
    const named = steps.find((l) => l.includes("pricing") && l.includes("refuse") && l.includes("409"));
    expect(named, `a step line naming pricing, refuse and 409:\n${proved.out}`).toBeDefined();
    nothingRunning(root);
  });

  it("a mount with no stand-in running fails the step, naming the mount and the command, and nothing is sent", () => {
    const { root, log } = app();
    const proved = prove(root, "a mount with no stand-in");
    expect(entriesOf(log).filter((e) => e.url.startsWith("/_stand/")), proved.out).toEqual([]);
    const { verdict, steps } = linesOf(proved.out, "a mount with no stand-in");
    expect(verdict, proved.out).toBe("journey a mount with no stand-in ✘ 0/1 steps");
    const named = steps.find((l) => l.includes("open") && l.includes("seed"));
    expect(named, `a step line naming open and seed:\n${proved.out}`).toBeDefined();
    nothingRunning(root);
  });
});
